/*IF( LEN(TEXT(MONTH(StartDate)))=0, 0,20) + IF( LEN(TEXT( ContractTerm ))=0, 0,20) + IF( LEN( BillingCity ) = 0, 0,20) + IF( LEN( CustomerSignedId) = 0, 0,20) + IF( ISPICKVAL( OwnerExpirationNotice ,""), 0,20)*/
IF( RecordType.DeveloperName="ER_Client_Contract_RT",
IF(LEN(CustomerSignedId)=0,0,11.11111112) + IF(AND(NOT(ISPICKVAL(Account.ER_Status__c,"Active")),LEN( TEXT(MONTH(EndDate)))=0),0,22.22222222) + IF(AND(NOT(ER_WS_Message__c="succeeded"), LEN(ER_Card_Operational_System_ID__c&ER_Paper_Operational_System_ID__c)=0),0,22.22222222) + IF(OR(ISPICKVAL(ER_InvoicingFrequency2__c,""),ISPICKVAL(ER_PaymentTerms2__c,"")),0,22.22222222) + IF(ISPICKVAL(ER_PaymentMethod2__c,""),0,22.22222222)
, IF(LEN(CustomerSignedId)=0,0,11.11111112) + IF(AND(NOT(ISPICKVAL(Account.ER_Status__c,"Active")),LEN( TEXT(MONTH(EndDate)))=0),0,22.22222222) + IF(AND(NOT(ER_WS_Message__c="succeeded"), LEN(ER_Card_Operational_System_ID__c&ER_Paper_Operational_System_ID__c)=0),0,22.22222222) + IF(OR(ISPICKVAL(ER_InvoicingFrequency2__c,""),ISPICKVAL(ER_PaymentTerms2__c,""),ISPICKVAL(ER_ReimbursementTerm2__c,"")),0,22.22222222) + IF(ISPICKVAL(ER_PaymentMethod2__c,""),0,22.22222222)
)
